-- ------------------------------------------------------------------------
-- 0094_masters_upsert_target.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- The master value lists could not be uploaded at all.
--
--   there is no unique or exclusion constraint matching the ON CONFLICT
--   specification — this register matches on name,value
--
-- The uniqueness masters carries is (name, value, stage, product), and the last
-- two are EXPRESSIONS over `extra` (0021, widened by 0044). `on conflict` cannot
-- infer an expression index, so the upsert was refused outright — the eighth
-- time this project has met that wall, and the first on a table where the
-- expressions were the point.
--
-- The fix is the same one 0076 used for the party key: STORED generated columns
-- that hold what the expressions computed, and a unique index on plain columns.
-- Nothing about the rule changes — "Calibration" may still exist for MONNAL T60
-- and for T75, and a Spare Approval Reason may still exist at two stages.
--
-- Filed under daily_review, not masters: 0044 owns the index this replaces, and
-- a migration that redefines something a LATER module owns is overwritten by it
-- on a fresh apply.
-- ===========================================================================

alter table public.masters
  add column if not exists stage_key   text generated always as (coalesce(extra->>'stage', ''))   stored,
  add column if not exists product_key text generated always as (coalesce(extra->>'product', '')) stored;

do $$
begin
  if exists (
    select 1 from public.masters
     group by name, value, coalesce(extra->>'stage', ''), coalesce(extra->>'product', '')
    having count(*) > 1
  ) then
    raise notice 'masters holds duplicate (name, value, stage, product) rows — de-duplicate, then re-run this file to build masters_name_value_keys_uniq.';
    return;
  end if;
  create unique index if not exists masters_name_value_keys_uniq
    on public.masters (name, value, stage_key, product_key);
  -- The expression index it replaces guarantees the same thing and can no
  -- longer be inferred by anything.
  drop index if exists public.masters_name_value_product_idx;
end $$;

-- ------------------------------------------------------------------------
-- 0047_daily_review_report_context.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0047 — What the reviewer needs from the REPORT, on the review row.
--
-- Reviewing a call means judging what the engineer actually found and did, so
-- the register carries the report alongside the three stages:
--
--   VISIT DETAILS      every visit, newest first, as "date : what was done" —
--                      the register's VISIT REMARKS column.
--   CALL STATUS        the latest visit's own status, and the call's open state.
--   SPARES CONSUMED    every spare booked against the call.
--   AGE OF THE PRODUCT how old the machine was when it failed — the days from
--                      warranty start to the complaint, and the register's
--                      banding of it ("With in 1 yr" … "More than 5 yrs").
--   SOFTWARE VERSION   as recorded on the latest visit.
--
-- All of it is DERIVED — nothing new is stored, and nothing has to be kept in
-- step by hand. `field_call_review` is rebuilt (dropped and created, not
-- replaced: replacing cannot reorder or drop a view's columns).
--
-- Idempotent.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. The register's own banding of a product's age at failure. Whole years
--    from warranty start, capped at 5 — the buckets the DCCR has always used.
-- ---------------------------------------------------------------------------
create or replace function public.failure_age_group(p_days integer)
returns text language sql immutable set search_path = public as $$
  select case
    when p_days is null or p_days < 0 then ''
    when p_days <  365 then 'With in 1 yr'
    when p_days <  730 then 'More than 1 yr'
    when p_days < 1095 then 'More than 2 yrs'
    when p_days < 1460 then 'More than 3 yrs'
    when p_days < 1825 then 'More than 4 yrs'
    else                    'More than 5 yrs'
  end;
$$;

-- ---------------------------------------------------------------------------
-- 2. The lookups the view makes per call, one index each.
--
--    The register is read NEWEST FIRST and a page at a time, so this index is
--    what keeps it cheap: without it the whole register is sorted before the
--    page is cut, and the per-call lookups below run for every row rather than
--    for the 500 being shown. (Measured on 25k calls / 50k visits: a page goes
--    from 13.7 s to 0.25 s.)
--    reports already has (ucn); the latest visit is picked by ENTRY —
--    updated_at desc, id desc — the same rule as sync_call_last_visit()
--    (0032_call_state_by_entry.sql), so this index serves that order directly.
-- ---------------------------------------------------------------------------
create index if not exists field_calls_reg_date_idx
  on public.field_calls (reg_date desc nulls last, id desc);
create index if not exists reports_ucn_entry_idx
  on public.reports (ucn, updated_at desc, id desc);
create index if not exists spare_consumption_ucn_idx
  on public.spare_consumption (ucn);
create index if not exists spare_consumption_call_number_idx
  on public.spare_consumption (call_number);

-- ---------------------------------------------------------------------------
-- 3. The register, with the report on the row.
-- ---------------------------------------------------------------------------
drop view if exists public.field_call_review;
create view public.field_call_review as
select
  c.id,
  c.ucn,
  c.call_number,
  c.reg_date,
  c.complaint_date,
  c.party_name,
  c.city,
  c.state,
  c.product_name,
  c.serial,
  c.item_status,
  c.call_type,
  c.standard_complaint,
  c.complaint_reported,
  c.allocated_to,
  c.allocated_to_email,
  c.warranty_number,
  c.warranty_start,
  c.status,
  c.open_state,
  c.last_status,
  c.last_visit_at,

  -- ---- age of the product at failure -------------------------------------
  -- Warranty start to the complaint (the call's registration date when there
  -- is no complaint date). Null when the machine has no warranty start on it.
  age.age_days,
  public.failure_age_group(age.age_days) as age_group,

  -- ---- from the report ----------------------------------------------------
  coalesce(h.visit_details, '')  as visit_details,   -- every visit, newest first
  coalesce(h.visit_count, 0)     as visit_count,
  coalesce(v.sw_version, '')     as sw_version,
  coalesce(v.observation, '')    as observation,     -- latest visit's finding
  coalesce(v.job_done, '')       as job_done,
  coalesce(v.pending_reason, '') as pending_reason,
  coalesce(v.visit_engineer, '') as visit_engineer,
  coalesce(sp.spares_consumed, '') as spares_consumed,
  coalesce(sp.spares_count, 0)     as spares_count,

  -- ---- Review 1 — from the call itself ------------------------------------
  c.public_health_threat,
  c.death,
  c.serious_incident,
  c.reg_date as review1_at,
  (btrim(coalesce(c.public_health_threat, '')) <> ''
   and btrim(coalesce(c.death, '')) <> ''
   and btrim(coalesce(c.serious_incident, '')) <> '') as review1_done,
  -- ---- Review 2 -----------------------------------------------------------
  coalesce(r.risk_to_patient, '')     as risk_to_patient,
  coalesce(r.warranty_failure, '')    as warranty_failure,
  coalesce(r.frequent_failure, '')    as frequent_failure,
  r.review2_at,
  coalesce(r.review2_by, '')          as review2_by,
  coalesce(r.review2_done, false)     as review2_done,
  -- ---- Review 3 -----------------------------------------------------------
  coalesce(r.complaint_grouping, '')  as complaint_grouping,
  coalesce(r.root_cause_keyword, '')  as root_cause_keyword,
  coalesce(r.spare_category, '')      as spare_category,
  coalesce(r.service_observation, '') as service_observation,
  r.review3_at,
  coalesce(r.review3_by, '')          as review3_by,
  coalesce(r.review3_done, false)     as review3_done,
  -- ---- Derived ------------------------------------------------------------
  coalesce(r.any_potential_effect, '') as any_potential_effect,
  coalesce(r.action_taken, '')         as action_taken,
  case
    when not (btrim(coalesce(c.public_health_threat, '')) <> ''
              and btrim(coalesce(c.death, '')) <> ''
              and btrim(coalesce(c.serious_incident, '')) <> '') then 'Review 1 Pending'
    when not coalesce(r.review2_done, false) then 'Review 2 Pending'
    when not coalesce(r.review3_done, false) then 'Review 3 Pending'
    else 'Review Completed'
  end as review_status
from public.field_calls c
left join public.call_reviews r on r.ucn = c.ucn

-- Age at failure.
left join lateral (
  select (coalesce(c.complaint_date, c.reg_date) - c.warranty_start)::int as age_days
) age on true

-- The LATEST visit, by entry (updated_at desc, id desc) — the same visit the
-- call's status comes from.
left join lateral (
  select nullif(btrim(coalesce(rp.data->>'Software Version', '')), '')      as sw_version,
         nullif(btrim(coalesce(rp.data->>'Complaint Observation', '')), '') as observation,
         nullif(btrim(coalesce(rp.data->>'Job Done', '')), '')              as job_done,
         nullif(btrim(coalesce(rp.pending_reason, '')), '')                 as pending_reason,
         nullif(btrim(coalesce(rp.engineer, '')), '')                       as visit_engineer
    from public.reports rp
   where rp.ucn = c.ucn
   order by rp.updated_at desc nulls last, rp.id desc
   limit 1
) v on true

-- EVERY visit, as the register writes them: "date : what was done", newest
-- first. A visit with nothing written still shows its date, so a call that was
-- attended and left blank does not read as never visited.
left join lateral (
  select string_agg(
           to_char(coalesce(rp.visit_at, rp.updated_at), 'DD-Mon-YYYY') || ' : ' ||
           coalesce(
             nullif(btrim(coalesce(rp.data->>'Job Done', '')), ''),
             nullif(btrim(coalesce(rp.data->>'Complaint Observation', '')), ''),
             ''),
           E'\n' order by rp.visit_at desc nulls last, rp.id desc) as visit_details,
         count(*) as visit_count
    from public.reports rp
   where rp.ucn = c.ucn
) h on true

-- Every spare booked against the call, with the quantity when it is not one.
left join lateral (
  select string_agg(
           btrim(s.part) || case
             when coalesce(s.qty, 1) = 1 then ''
             -- A whole number reads as "x 2", not "x 2." (FM keeps the point).
             when s.qty = trunc(s.qty) then ' x ' || trunc(s.qty)::bigint::text
             else ' x ' || trim(to_char(s.qty, 'FM999999.999'))
           end,
           ', ' order by s.id) as spares_consumed,
         count(*) as spares_count
    from public.spare_consumption s
   where s.ucn = c.ucn and btrim(coalesce(s.part, '')) <> ''
) sp on true;

alter view public.field_call_review set (security_invoker = on);
grant select on public.field_call_review to authenticated;

-- ---------------------------------------------------------------------------
-- 4. The same register WITHOUT the per-call report lookups.
--
--    The module's stage counters ask "how many of the whole filtered set are
--    at each stage", which the full view cannot answer cheaply: the report and
--    spares lookups would run for every row counted, not just the page shown
--    (3 s over a year of calls). This carries only what a count filters on and
--    groups by, so counting is a plain scan of the two tables.
-- ---------------------------------------------------------------------------
drop view if exists public.field_call_review_summary;
create view public.field_call_review_summary as
select
  c.id,
  c.ucn,
  c.reg_date,
  c.product_name,
  c.allocated_to,
  c.party_name,
  c.serial,
  coalesce(r.any_potential_effect, '') as any_potential_effect,
  case
    when not (btrim(coalesce(c.public_health_threat, '')) <> ''
              and btrim(coalesce(c.death, '')) <> ''
              and btrim(coalesce(c.serious_incident, '')) <> '') then 'Review 1 Pending'
    when not coalesce(r.review2_done, false) then 'Review 2 Pending'
    when not coalesce(r.review3_done, false) then 'Review 3 Pending'
    else 'Review Completed'
  end as review_status
from public.field_calls c
left join public.call_reviews r on r.ucn = c.ucn;

alter view public.field_call_review_summary set (security_invoker = on);
grant select on public.field_call_review_summary to authenticated;

-- ------------------------------------------------------------------------
-- 0111_dccr_call_status.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE DAILY CALL REVIEW CAN FILTER BY CALL STATUS.
--
-- The review register's existing status filter is the REVIEW status — Review 1
-- / 2 / 3 Pending, Review Completed. That is a fact about the paperwork. The
-- other question the desk asks of the same list is a fact about the MACHINE:
-- is the call still open, was it solved, was it cancelled.
--
-- The full view (`field_call_review`) already carries `open_state`. The SUMMARY
-- view does not — and the summary is what the stage counters are read from, so
-- a filter the rows honoured and the counts did not would make the register
-- disagree with its own header. It carries `open_state` and `cancelled_at` now.
--
-- APPENDED, not inserted. `create or replace view` can only add columns at the
-- END; putting one in the middle fails with "cannot change name of view
-- column". Both go last, and the view is REPLACED rather than dropped so
-- nothing built on it has to be rebuilt.
--
-- THE FILTER USES `open_state` ONLY, for now. `field_call_review` — the full
-- view the rows come from — carries open_state but NOT cancelled_at, and it is
-- a large view with three lateral joins; appending a column to it is a change
-- worth making on its own rather than as a rider here. So the register can be
-- filtered to Unattended / Unsolved / Report pending / Solved, and a cancelled
-- call still shows under whichever of those its visits last said.
-- `cancelled_at` is carried here so that filter can be added without another
-- migration to this view.
--
-- `security_invoker` is re-asserted because `create or replace view` DROPS it,
-- and a view without it reads as its OWNER — which is how every signed-in user
-- could once read every call. This one reads `field_calls`, so it matters.
-- ===========================================================================

create or replace view public.field_call_review_summary as
select
  c.id,
  c.ucn,
  c.reg_date,
  c.product_name,
  c.allocated_to,
  c.party_name,
  c.serial,
  coalesce(r.any_potential_effect, '') as any_potential_effect,
  case
    when not (btrim(coalesce(c.public_health_threat, '')) <> ''
              and btrim(coalesce(c.death, '')) <> ''
              and btrim(coalesce(c.serious_incident, '')) <> '') then 'Review 1 Pending'
    when not coalesce(r.review2_done, false) then 'Review 2 Pending'
    when not coalesce(r.review3_done, false) then 'Review 3 Pending'
    else 'Review Completed'
  end as review_status,
  -- Appended (see the header). The call's own state, so the register can be
  -- asked "which of these are still open?" and have the counters agree.
  c.open_state,
  c.cancelled_at
from public.field_calls c
left join public.call_reviews r on r.ucn = c.ucn;

alter view public.field_call_review_summary set (security_invoker = on);
grant select on public.field_call_review_summary to authenticated;

-- ------------------------------------------------------------------------
-- 0117_frequent_failure.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- IS THIS A FREQUENT FAILURE?  Let the register answer, not somebody's memory.
--
-- Review 2 asks three questions and one of them is "Frequent Failure". Until
-- now the reviewer answered it from what they happened to remember about the
-- machine. The register already knows: the user's rule (2026-09-06) is
--
--     failures on the SAME PRODUCT + SERIAL NUMBER, with the SAME COMPLAINT,
--     in the last 6 MONTHS.
--
-- So this returns those calls — not just a count. A number on its own invites
-- "which ones?", and the reviewer is about to record a judgement they may have
-- to defend; the UCNs and dates are what makes it defensible. The screen shows
-- the count and lists them underneath.
--
-- WHAT "SAME COMPLAINT" MEANS, and why it is two tests. `standard_complaint` is
-- the controlled value and the right one to match on — but the sheet era left
-- calls with none, and an imported call with only a reported problem would
-- silently match nothing and read as "no history". So: the standard complaints
-- match, OR the reported problems match, each compared on lower(btrim()).
--
-- THE WINDOW IS MEASURED FROM THE CALL, not from today. A review done in March
-- on a call raised in January must see January's six months, or reopening an
-- old review changes its answer.
--
-- THE CALL ITSELF IS EXCLUDED. "Two earlier failures" is what a reviewer needs
-- to hear; a count that silently includes the call being reviewed reads as one
-- more than it is, and this is the number the Yes/No is decided on.
--
-- SECURITY DEFINER, deliberately. The question is about a MACHINE the reader is
-- already reviewing, and an answer filtered by their own call scope would show
-- a smaller number than the truth — which is the one direction that matters
-- here, because it would talk somebody out of raising an FFR. Gated on the
-- review permission, and it returns nothing that is not about this machine.
-- ===========================================================================

create or replace function public.frequent_failure_history(p_ucn text, p_months integer default 6)
returns table (
  ucn            text,
  call_number    text,
  reg_date       date,
  complaint      text,
  engineer       text,
  party_name     text,
  days_before    integer
)
language plpgsql stable security definer set search_path = public as $$
declare
  v_product   text;
  v_serial    text;
  v_std       text;
  v_reported  text;
  v_on        date;
  v_months    integer := greatest(coalesce(p_months, 6), 1);
begin
  if not (public.has_perm('review.edit') or public.has_perm('calls.view')) then
    raise exception 'RBAC: your role cannot read the review history';
  end if;

  select lower(btrim(coalesce(c.product_name, ''))),
         lower(btrim(coalesce(c.serial, ''))),
         lower(btrim(coalesce(c.standard_complaint, ''))),
         lower(btrim(coalesce(c.complaint_reported, ''))),
         c.reg_date
    into v_product, v_serial, v_std, v_reported, v_on
    from public.calls c where c.ucn = p_ucn;

  -- No machine to compare, no answer. A blank serial would otherwise match
  -- every other call that is also missing one, which is the worst kind of
  -- wrong: a confident number built out of absent data.
  if v_product is null or v_product = '' or v_serial = '' then return; end if;
  v_on := coalesce(v_on, current_date);

  return query
  select c.ucn,
         coalesce(c.call_number, '')          as call_number,
         c.reg_date,
         coalesce(nullif(btrim(c.standard_complaint), ''), c.complaint_reported, '') as complaint,
         coalesce(c.allocated_to, '')         as engineer,
         coalesce(c.party_name, '')           as party_name,
         (v_on - c.reg_date)::integer         as days_before
    from public.calls c
   where c.ucn <> p_ucn
     and lower(btrim(coalesce(c.product_name, ''))) = v_product
     and lower(btrim(coalesce(c.serial, '')))       = v_serial
     and c.reg_date is not null
     and c.reg_date <= v_on
     and c.reg_date >  v_on - make_interval(months => v_months)
     and c.cancelled_at is null
     and (
       (v_std <> '' and lower(btrim(coalesce(c.standard_complaint, ''))) = v_std)
       or
       (v_reported <> '' and lower(btrim(coalesce(c.complaint_reported, ''))) = v_reported)
     )
   order by c.reg_date desc, c.ucn desc;
end $$;
revoke all on function public.frequent_failure_history(text, integer) from public;
grant execute on function public.frequent_failure_history(text, integer) to authenticated;

comment on function public.frequent_failure_history(text, integer) is
  'Earlier failures on the same product+serial with the same complaint, within p_months BEFORE the call''s own date. Excludes the call itself. Feeds the Frequent Failure answer at DCCR Review 2.';

-- ------------------------------------------------------------------------
-- 0153_frequent_failure_rule.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- FREQUENT FAILURE — the PROCEDURE'S rule, not the first approximation of it.
--
-- Reported 2026-09-09: the Review 2 helper "still not fixed". It was not. The
-- rule has been settled in docs/BACKLOG.md since 2026-09-06 and 0117 only ever
-- implemented part of it. Three differences, all of which change the answer:
--
--   |         | Procedure                          | 0117                     |
--   | Window  | ONE MONTH                          | six months               |
--   | Count   | >= 2 INCLUDING the call in review  | listed priors only, so   |
--   |         | -- so ONE prior failure is enough  | a reviewer read 1 where  |
--   |         |                                    | the rule counts 2        |
--   | Match   | same equipment OR the SAME PART    | same equipment only, and |
--   |         | in the same machine                | complaints had to match  |
--
-- The window being 6x too wide flagged failures the procedure would not, which
-- inflates the frequent-failure figure feeding the objectives. The count was
-- off by one against the rule as written. And the "same part in the same
-- machine" path -- the user's own words, "Same Part in same Machine" -- did not
-- exist at all.
--
-- EDITABLE, because the user asked for that in the same breath ("Maybe make it
-- editable in Admin Pannel"): window, threshold and one judgement call below
-- live in `app_settings`, which is already admin-only to write (0047). The
-- defaults here ARE the procedure, so a project that never opens Admin Config
-- gets the procedure.
--
-- THE ONE JUDGEMENT CALL, stated rather than buried. The procedure says "same
-- equipment"; the user's rule of 2026-09-06 said the complaint had to match
-- too. Both readings are defensible and they give different answers, so it is a
-- SETTING (`ffr.equipment_needs_complaint`) and it DEFAULTS TO ON -- the
-- behaviour this system has had since 0117. A rule change that silently
-- re-bases past judgements is the one thing not to do here.
--
-- ANSWERS ALREADY RECORDED ARE LEFT ALONE. 0124 auto-answers Review 2 on a
-- schedule, so some of these are stamped "Auto (9:15 am)" -- and every one of
-- them is a quality record. This migration does not touch `daily_call_review`:
-- nothing is re-opened, re-answered or withdrawn. Re-reviewing calls decided
-- under the old window is a deliberate act for RA/QA, not a side effect of a
-- migration, and the screen now shows the rule it is applying so the two are
-- told apart. That decision remains open in docs/BACKLOG.md.
--
-- WHAT IS UNCHANGED FROM 0117, because it was right:
--   * The window is measured from THE CALL'S date, not today, or reopening an
--     old review would change its answer.
--   * A blank serial returns nothing rather than matching every other
--     blank-serial call. `known` says so, and the screen says "cannot tell"
--     rather than "no" -- this decides whether an FFR is raised.
--   * SECURITY DEFINER: an answer filtered by the reader's own call scope would
--     read LOWER than the truth, and low is the direction that talks somebody
--     out of raising an FFR. Gated on the review permission; it returns nothing
--     that is not about the machine already on screen.
-- ===========================================================================

-- ---- the rule, as settings -------------------------------------------------
insert into public.app_settings (key, value, updated_at) values
  ('ffr.window_months', '1', now()),
  ('ffr.threshold', '2', now()),
  ('ffr.equipment_needs_complaint', 'on', now())
on conflict (key) do nothing;      -- never overwrite what an admin has tuned

create or replace function public.frequent_failure_rule()
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'window_months', greatest(coalesce((select nullif(btrim(value), '')::integer
                                          from public.app_settings where key = 'ffr.window_months'), 1), 1),
    'threshold',     greatest(coalesce((select nullif(btrim(value), '')::integer
                                          from public.app_settings where key = 'ffr.threshold'), 2), 1),
    'equipment_needs_complaint',
                     coalesce((select lower(btrim(value)) = 'on'
                                 from public.app_settings where key = 'ffr.equipment_needs_complaint'), true));
$$;

revoke all on function public.frequent_failure_rule() from public;
grant execute on function public.frequent_failure_rule() to authenticated;

comment on function public.frequent_failure_rule() is
  'The frequent-failure rule in force: window_months, threshold (counted INCLUDING the call under review) and whether the same-equipment path also requires a matching complaint. Defaults are the procedure''s own (1 month, 2, on) and apply when app_settings carries nothing (0153).';

-- ---- the answer ------------------------------------------------------------
-- The old signature returned rows and no verdict, so the screen had to apply
-- the threshold itself -- which is how the count came to be read one short.
-- One function, one rule, one place to change it.
drop function if exists public.frequent_failure_history(text, integer);

create or replace function public.frequent_failure(p_ucn text)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_rule      jsonb := public.frequent_failure_rule();
  v_months    integer := (v_rule ->> 'window_months')::integer;
  v_threshold integer := (v_rule ->> 'threshold')::integer;
  v_needs_c   boolean := (v_rule ->> 'equipment_needs_complaint')::boolean;
  v_product   text;
  v_serial    text;
  v_std       text;
  v_reported  text;
  v_on        date;
  v_rows      jsonb;
  v_earlier   integer;
begin
  if not (public.has_perm('review.edit') or public.has_perm('calls.view')) then
    raise exception 'RBAC: your role cannot read the review history';
  end if;

  select lower(btrim(coalesce(c.product_name, ''))),
         lower(btrim(coalesce(c.serial, ''))),
         lower(btrim(coalesce(c.standard_complaint, ''))),
         lower(btrim(coalesce(c.complaint_reported, ''))),
         c.reg_date
    into v_product, v_serial, v_std, v_reported, v_on
    from public.calls c where c.ucn = p_ucn;

  -- No machine, no answer -- and say which, because "no history" and "cannot
  -- tell" are different things to record a judgement on.
  if v_product is null or v_product = '' or v_serial = '' then
    return v_rule || jsonb_build_object(
      'known', false, 'earlier', 0, 'total', 0, 'is_frequent', false, 'rows', '[]'::jsonb);
  end if;
  v_on := coalesce(v_on, current_date);

  with mine as (
    -- The parts fitted on the call under review, by CODE. The code is the half
    -- that is stable: descriptions drift, and both sides store CODE|Description.
    select distinct btrim(split_part(sc.part, '|', 1)) as code
      from public.spare_consumption sc
     where (sc.ucn = p_ucn or (nullif(btrim(sc.call_number), '') is not null
            and sc.call_number = (select c.call_number from public.calls c where c.ucn = p_ucn)))
       and coalesce(sc.qty, 0) > 0            -- a VOIDED line is not consumption
       and btrim(split_part(sc.part, '|', 1)) <> ''
  ),
  -- Every earlier call on the SAME MACHINE inside the window. The two match
  -- paths are then tested against this one set, so a call that satisfies both
  -- is one row, not two.
  machine as (
    select c.*
      from public.calls c
     where c.ucn <> p_ucn
       and lower(btrim(coalesce(c.product_name, ''))) = v_product
       and lower(btrim(coalesce(c.serial, '')))       = v_serial
       and c.reg_date is not null
       and c.reg_date <= v_on
       and c.reg_date >  v_on - make_interval(months => v_months)
       and c.cancelled_at is null
  ),
  matched as (
    select m.ucn,
           coalesce(m.call_number, '')  as call_number,
           m.reg_date,
           coalesce(nullif(btrim(m.standard_complaint), ''), m.complaint_reported, '') as complaint,
           coalesce(m.allocated_to, '') as engineer,
           coalesce(m.party_name, '')   as party_name,
           (v_on - m.reg_date)::integer as days_before,
           -- SAME COMPLAINT, on the standard value or the reported wording:
           -- the sheet era left calls with no standard complaint, and one of
           -- those would otherwise read as "no history".
           ((v_std <> '' and lower(btrim(coalesce(m.standard_complaint, ''))) = v_std)
             or (v_reported <> '' and lower(btrim(coalesce(m.complaint_reported, ''))) = v_reported)
           ) as same_complaint,
           exists (
             select 1 from public.spare_consumption sc
              where (sc.ucn = m.ucn or (nullif(btrim(sc.call_number), '') is not null
                     and sc.call_number = m.call_number))
                and coalesce(sc.qty, 0) > 0
                and btrim(split_part(sc.part, '|', 1)) in (select code from mine)
           ) as same_part
      from machine m
  ),
  kept as (
    select *,
           case when same_part then 'Same part in this machine'
                when same_complaint then 'Same machine, same complaint'
                else 'Same machine' end as match_on
      from matched
     -- The same part in the same machine ALWAYS counts -- that is the path the
     -- procedure adds and it does not mention the complaint. The equipment path
     -- is where the judgement call lives.
     where same_part or (not v_needs_c) or same_complaint
  )
  select coalesce(jsonb_agg(to_jsonb(k) order by k.reg_date desc, k.ucn desc), '[]'::jsonb), count(*)
    into v_rows, v_earlier
    from kept k;

  return v_rule || jsonb_build_object(
    'known', true,
    'earlier', v_earlier,
    -- INCLUDING THE CALL UNDER REVIEW. That is the rule as the user stated it
    -- ("2 or More including the call in question"), and the reason the old
    -- screen read one short.
    'total', v_earlier + 1,
    'is_frequent', (v_earlier + 1) >= v_threshold,
    'rows', v_rows);
end $$;

revoke all on function public.frequent_failure(text) from public;
grant execute on function public.frequent_failure(text) to authenticated;

comment on function public.frequent_failure(text) is
  'Is this a frequent failure? Earlier calls on the same machine within the window, matched on the same complaint OR the same part fitted, counted INCLUDING the call under review against the threshold (0153). Replaces frequent_failure_history(), which listed priors and left the screen to apply the rule. SECURITY DEFINER on purpose: an answer narrowed to the reader''s own call scope would read lower than the truth, and low is the direction that talks somebody out of raising an FFR.';

-- ------------------------------------------------------------------------
-- 0119_bulk_review2.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- ANSWER REVIEW 2 FOR MANY CALLS AT ONCE — EXCEPT THE ONES THAT MATTER MOST.
--
-- The user's rule (2026-09-06): "If the Age at failure is less than 366, then
-- it has to be done 1 by 1. If it is not, then it can be bulk set."
--
-- That rule is the whole point of the function, not a caveat on it. Review 2
-- asks whether a failure was a WARRANTY FAILURE (1 yr) — so a machine that
-- failed inside its first year is precisely the case the question exists for,
-- and precisely the one nobody should answer forty at a time. Everything older
-- is the routine bulk of the register, and clicking NO three times on each of
-- them is the work this removes.
--
-- ENFORCED HERE, not only on the screen. The client hides those rows from the
-- selection, but a hidden checkbox is a convenience and this is a quality
-- record: the rule has to hold against anything that can reach the API.
--
-- AN UNKNOWN AGE IS ALSO DONE ONE BY ONE. A machine with no warranty start has
-- no age, and "not known to be inside its first year" is not the same as
-- "known to be outside it". Answering "not a warranty failure" in bulk for a
-- machine whose age nobody can state is the one direction that cannot be
-- defended afterwards. If that turns out to exclude too much of the register,
-- it is one line to change — but it should be changed deliberately, with the
-- numbers in front of somebody.
--
-- IT DOES NOT OVERWRITE AN ANSWER. A call whose Review 2 is already complete
-- is skipped: bulk is for clearing what is pending, and silently rewriting a
-- judgement somebody already made is not something a button should do.
--
-- Like the spare batches (0116/0118), it SKIPS and COUNTS rather than failing:
-- a selection of two hundred that stops on the first ineligible one is a
-- selection you then take apart by hand.
-- ===========================================================================

create or replace function public.bulk_set_review2(
  p_ucns     text[],
  p_risk     text,
  p_warranty text,
  p_frequent text,
  p_by       text default ''
)
returns table (updated integer, skipped integer, reason text)
language plpgsql security definer set search_path = public as $$
declare
  v_ucn   text;
  v_age   integer;
  v_done  boolean;
  v_by    text := nullif(btrim(coalesce(p_by, '')), '');
  n_ok    integer := 0;
  n_skip  integer := 0;
  why     text[]  := '{}';
begin
  if not public.has_perm('review.edit') then
    raise exception 'RBAC: your role cannot complete the daily call review';
  end if;
  if p_ucns is null or array_length(p_ucns, 1) is null then
    raise exception 'Nothing selected';
  end if;
  -- All three, or it is not an answer to Review 2.
  if btrim(coalesce(p_risk, '')) = '' or btrim(coalesce(p_warranty, '')) = ''
     or btrim(coalesce(p_frequent, '')) = '' then
    raise exception 'Review 2 needs all three answers';
  end if;

  v_by := coalesce(v_by, public.my_dir_name(), auth.email(), '');

  foreach v_ucn in array p_ucns loop
    -- The SAME age 0047 shows on the screen: from the complaint (falling back
    -- to registration) to the machine's warranty start. Computed here rather
    -- than trusted from the caller — the caller is what this is guarding.
    select (coalesce(c.complaint_date, c.reg_date) - c.warranty_start)::int
      into v_age
      from public.field_calls c where c.ucn = v_ucn;

    if not found then
      n_skip := n_skip + 1; why := array_append(why, 'no such call'); continue;
    end if;

    if v_age is null then
      n_skip := n_skip + 1;
      why := array_append(why, 'age at failure not known — review it one by one');
      continue;
    end if;

    if v_age < 366 then
      n_skip := n_skip + 1;
      why := array_append(why, 'failed within the first year — review it one by one');
      continue;
    end if;

    select r.review2_done into v_done from public.call_reviews r where r.ucn = v_ucn;
    if coalesce(v_done, false) then
      n_skip := n_skip + 1; why := array_append(why, 'Review 2 already answered'); continue;
    end if;

    -- review2_at and the derived columns are the table's own business
    -- (call_reviews_stamp); this sets the answers and who gave them.
    insert into public.call_reviews (ucn, call_number, risk_to_patient, warranty_failure, frequent_failure, review2_by)
    select v_ucn, coalesce(c.call_number, ''), btrim(p_risk), btrim(p_warranty), btrim(p_frequent), v_by
      from public.field_calls c where c.ucn = v_ucn
    on conflict (ucn) do update
       set risk_to_patient  = excluded.risk_to_patient,
           warranty_failure = excluded.warranty_failure,
           frequent_failure = excluded.frequent_failure,
           review2_by       = excluded.review2_by;

    n_ok := n_ok + 1;
  end loop;

  return query select n_ok, n_skip,
    coalesce((select string_agg(w, '; ') from (select distinct unnest(why) as w) d), '');
end $$;
revoke all on function public.bulk_set_review2(text[], text, text, text, text) from public;
grant execute on function public.bulk_set_review2(text[], text, text, text, text) to authenticated;

comment on function public.bulk_set_review2(text[], text, text, text, text) is
  'Answer Review 2 for many calls at once. REFUSES a call that failed inside its first year (age < 366 days) or whose age is unknown — those are reviewed one by one — and never overwrites a Review 2 already answered.';

-- ------------------------------------------------------------------------
-- 0124_auto_review2.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- REVIEW 2 ANSWERS ITSELF THE MORNING AFTER, AND NOT BEFORE.
--
-- The user's rule (2026-09-06): "if a call is logged Today, Review 2 should be
-- marked as No tomorrow. It should still be pending for review today; it can be
-- marked as No the next day - 9:15 am. During Review 3, I will change it if
-- need be."
--
-- So there are TWO conditions, and the second is the one that is easy to lose:
--   * the call was logged BEFORE today — a call logged today stays pending all
--     day, because today is when somebody is supposed to look at it;
--   * it is 9:15 am or later. Before that, the day has not started and nothing
--     is marked. The check lives in the FUNCTION, not only in the schedule, so
--     the answer is the same whoever calls it and however often.
--
-- Both are measured in Asia/Kolkata. The database's `current_date` is UTC, and
-- at 9:15 in India that is still the previous day for part of the year's worth
-- of edge cases; "today" here has to mean the reviewer's today.
--
-- WHAT IT DOES NOT TOUCH
--
--   * A call that failed inside its FIRST YEAR (age < 366 days). That is the
--     user's own rule from bulk Review 2 (0119) and it applies with more force
--     here, not less: Review 2 asks whether this was a warranty failure, so a
--     machine that failed in its first year is precisely the case the question
--     exists for. A clock must not answer it.
--   * A call whose age at failure is UNKNOWN — no warranty start, so no age.
--     "Not known to be inside its first year" is not "known to be outside it",
--     and this is a quality record.
--   * A Review 2 somebody has already answered. It fills in what is blank.
--
-- The held-back ones are COUNTED and returned, so the number of calls the
-- automation is deliberately leaving for a person is a figure somebody can
-- look at rather than a silence.
--
-- WHO ANSWERED IT is recorded as 'Auto (9:15 am)' in review2_by, so Review 3
-- can tell an automatic NO from one a reviewer gave — which is the whole basis
-- on which the user said they would change it if need be.
--
-- THE FIRST RUN CLEARS THE BACKLOG. Every call still pending Review 2 that was
-- logged before today and failed outside its first year is answered in that one
-- run, however far back it goes. That is what automating it means, but it is a
-- bulk write to a quality record and it happens the moment this file is
-- applied — so it is said here rather than discovered afterwards.
--
-- TO UNDO IT, all of it or one day of it, the marker is the whole point:
--
--   update public.call_reviews
--      set risk_to_patient = '', warranty_failure = '', frequent_failure = '',
--          review2_by = '', review2_at = null
--    where review2_by = 'Auto (9:15 am)';        -- add: and review2_at = date '...'
--
-- Nothing a person answered carries that marker, so nothing a person answered
-- can be caught by it.
-- ===========================================================================

-- TESTABLE AT A FIXED MOMENT, AND ONLY FROM INSIDE. The rule is entirely about
-- what time it is, so it is split in two: a worker that takes the moment, and
-- the entry point that supplies the real one. The worker is granted to NOBODY
-- — no signed-in caller can hand it a clock and mark today's calls early.

create or replace function public.auto_answer_review2_asof(p_asof timestamptz)
returns table (marked integer, held_first_year integer, held_unknown_age integer, ran boolean, note text)
language plpgsql security definer set search_path = public as $$
declare
  v_today date := (p_asof at time zone 'Asia/Kolkata')::date;
  v_time  time := (p_asof at time zone 'Asia/Kolkata')::time;
  n_ok    integer := 0;
  n_year  integer := 0;
  n_age   integer := 0;
begin
  if v_time < time '09:15' then
    return query select 0, 0, 0, false, 'before 9:15 am — nothing is marked yet today'::text;
    return;
  end if;

  -- Everything still pending that was logged before today. `reg_at` is the
  -- registration timestamp where there is one (0050); `reg_date` is the date
  -- the call is filed under, and is what the register has always shown.
  with pending as (
    select c.ucn,
           coalesce(c.call_number, '') as call_number,
           (coalesce(c.complaint_date, c.reg_date) - c.warranty_start)::int as age_at_failure
      from public.field_calls c
      left join public.call_reviews r on r.ucn = c.ucn
     where coalesce((c.reg_at at time zone 'Asia/Kolkata')::date, c.reg_date) < v_today
       and not coalesce(r.review2_done, false)
  ),
  held as (
    select count(*) filter (where age_at_failure is not null and age_at_failure < 366) as first_year,
           count(*) filter (where age_at_failure is null)                              as unknown_age
      from pending
  ),
  done as (
    insert into public.call_reviews as cr
      (ucn, call_number, risk_to_patient, warranty_failure, frequent_failure, review2_by)
    select p.ucn, p.call_number, 'NO', 'NO', 'NO', 'Auto (9:15 am)'
      from pending p
     where p.age_at_failure is not null and p.age_at_failure >= 366
    on conflict (ucn) do update
       set risk_to_patient  = excluded.risk_to_patient,
           warranty_failure = excluded.warranty_failure,
           frequent_failure = excluded.frequent_failure,
           review2_by       = excluded.review2_by
     where not coalesce(cr.review2_done, false)
    returning 1
  )
  select (select count(*) from done), h.first_year, h.unknown_age
    into n_ok, n_year, n_age
    from held h;

  return query select n_ok, n_year, n_age, true,
    (case when n_ok = 0 then 'nothing was waiting'
          else n_ok || ' answered No' end
     || case when n_year + n_age > 0
             then format('; %s left for a person (%s failed inside the first year, %s with no age on record)',
                         n_year + n_age, n_year, n_age)
             else '' end)::text;
end $$;

-- Nobody may call the worker directly: it is the one place a clock could be
-- handed in, and the entry point below is the only caller.
revoke all on function public.auto_answer_review2_asof(timestamptz) from public;

create or replace function public.auto_answer_review2()
returns table (marked integer, held_first_year integer, held_unknown_age integer, ran boolean, note text)
language plpgsql security definer set search_path = public as $$
begin
  -- Called by pg_cron there is no signed-in user, and the schedule IS the
  -- authority. Called from a screen there is one, and it must be somebody who
  -- could have given the answer by hand.
  if auth.uid() is not null and not public.has_perm('review.edit') then
    raise exception 'RBAC: your role cannot complete the daily call review';
  end if;
  return query select * from public.auto_answer_review2_asof(now());
end $$;

revoke all on function public.auto_answer_review2() from public;
grant execute on function public.auto_answer_review2() to authenticated;

comment on function public.auto_answer_review2() is
  'Marks Review 2 as No for every call logged BEFORE today, from 9:15 am Asia/Kolkata. Never touches a first-year failure, a call whose age at failure is unknown, or a Review 2 already answered; records itself as "Auto (9:15 am)" so Review 3 can tell.';

-- ---------------------------------------------------------------------------
-- Daily at 09:15 Asia/Kolkata = 03:45 UTC. Same guarded shape as 0033: enable
-- pg_cron if we can, say so plainly if we cannot, and never fail the migration
-- over it — the register calls the same function when it loads, so the rule
-- still applies on a project without pg_cron. It just applies when somebody
-- opens the screen rather than at a quarter past nine.
-- ---------------------------------------------------------------------------
do $$
begin
  create extension if not exists pg_cron;
exception when others then
  raise notice 'Could not enable pg_cron automatically (%). Enable it in Dashboard -> Database -> Extensions, then re-run this file.', sqlerrm;
end $$;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if exists (select 1 from cron.job where jobname = 'auto-answer-review2') then
      perform cron.unschedule('auto-answer-review2');
    end if;
    perform cron.schedule('auto-answer-review2', '45 3 * * *', 'select public.auto_answer_review2();');
    raise notice 'Scheduled auto-answer-review2 at 03:45 UTC = 09:15 Asia/Kolkata.';
  else
    raise notice 'pg_cron is not enabled. Review 2 will still auto-answer, but only when somebody opens the Daily Call Review after 9:15 am. Enable pg_cron (Dashboard -> Database -> Extensions) and re-run this file for the scheduled run.';
  end if;
exception when others then
  raise notice 'Could not schedule auto-answer-review2 (%). The register calls the same function on load, so the rule still applies.', sqlerrm;
end $$;

-- ------------------------------------------------------------------------
-- 0048_daily_review_map_by_call_number.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0048 — Map the visits and the spares to a call by CALL NUMBER.
--
-- 0047 matched `reports` and `spare_consumption` to a call on `ucn` alone, so
-- a call whose visits and consumption are keyed by Call Number read as though
-- it had never been attended: "no visit reported yet" and "no spare booked"
-- on a call the Field Call view shows two visits and a consumed spare for.
--
-- Call Number is what associates them. It is what the Field Call view's own
-- panels read (reportsByCall / spareConsumptionByCall in src/lib/supabase.ts
-- both filter on call_number), and what CallReporting writes against.
--
-- So both lookups now match on EITHER key: the call number when the call has
-- one, or the UCN. A row written by the app carries both; a row that came in
-- from the register may carry only one, and either way it belongs to the call.
-- Blank keys never match — an empty call_number would otherwise sweep in every
-- other row that also has none.
--
-- Idempotent.
-- ===========================================================================

-- The call-number side of both lookups, so matching on either key stays cheap.
-- (reports already has (ucn) and (call_number); this adds the entry ordering
-- the latest-visit pick uses, keyed by call number.)
create index if not exists reports_call_number_entry_idx
  on public.reports (call_number, updated_at desc, id desc);

drop view if exists public.field_call_review;
create view public.field_call_review as
select
  c.id,
  c.ucn,
  c.call_number,
  c.reg_date,
  c.complaint_date,
  c.party_name,
  c.city,
  c.state,
  c.product_name,
  c.serial,
  c.item_status,
  c.call_type,
  c.standard_complaint,
  c.complaint_reported,
  c.allocated_to,
  c.allocated_to_email,
  c.warranty_number,
  c.warranty_start,
  c.status,
  c.open_state,
  c.last_status,
  c.last_visit_at,

  -- ---- age of the product at failure -------------------------------------
  -- Warranty start to the complaint (the call's registration date when there
  -- is no complaint date). Null when the machine has no warranty start on it.
  age.age_days,
  public.failure_age_group(age.age_days) as age_group,

  -- ---- from the report ----------------------------------------------------
  coalesce(h.visit_details, '')  as visit_details,   -- every visit, newest first
  coalesce(h.visit_count, 0)     as visit_count,
  coalesce(v.sw_version, '')     as sw_version,
  coalesce(v.observation, '')    as observation,     -- latest visit's finding
  coalesce(v.job_done, '')       as job_done,
  coalesce(v.pending_reason, '') as pending_reason,
  coalesce(v.visit_engineer, '') as visit_engineer,
  coalesce(sp.spares_consumed, '') as spares_consumed,
  coalesce(sp.spares_count, 0)     as spares_count,

  -- ---- Review 1 — from the call itself ------------------------------------
  c.public_health_threat,
  c.death,
  c.serious_incident,
  c.reg_date as review1_at,
  (btrim(coalesce(c.public_health_threat, '')) <> ''
   and btrim(coalesce(c.death, '')) <> ''
   and btrim(coalesce(c.serious_incident, '')) <> '') as review1_done,
  -- ---- Review 2 -----------------------------------------------------------
  coalesce(r.risk_to_patient, '')     as risk_to_patient,
  coalesce(r.warranty_failure, '')    as warranty_failure,
  coalesce(r.frequent_failure, '')    as frequent_failure,
  r.review2_at,
  coalesce(r.review2_by, '')          as review2_by,
  coalesce(r.review2_done, false)     as review2_done,
  -- ---- Review 3 -----------------------------------------------------------
  coalesce(r.complaint_grouping, '')  as complaint_grouping,
  coalesce(r.root_cause_keyword, '')  as root_cause_keyword,
  coalesce(r.spare_category, '')      as spare_category,
  coalesce(r.service_observation, '') as service_observation,
  r.review3_at,
  coalesce(r.review3_by, '')          as review3_by,
  coalesce(r.review3_done, false)     as review3_done,
  -- ---- Derived ------------------------------------------------------------
  coalesce(r.any_potential_effect, '') as any_potential_effect,
  coalesce(r.action_taken, '')         as action_taken,
  case
    when not (btrim(coalesce(c.public_health_threat, '')) <> ''
              and btrim(coalesce(c.death, '')) <> ''
              and btrim(coalesce(c.serious_incident, '')) <> '') then 'Review 1 Pending'
    when not coalesce(r.review2_done, false) then 'Review 2 Pending'
    when not coalesce(r.review3_done, false) then 'Review 3 Pending'
    else 'Review Completed'
  end as review_status
from public.field_calls c
left join public.call_reviews r on r.ucn = c.ucn

-- Age at failure.
left join lateral (
  select (coalesce(c.complaint_date, c.reg_date) - c.warranty_start)::int as age_days
) age on true

-- The LATEST visit, by entry (updated_at desc, id desc) — the same visit the
-- call's status comes from (sync_call_last_visit, 0032).
left join lateral (
  select nullif(btrim(coalesce(rp.data->>'Software Version', '')), '')      as sw_version,
         nullif(btrim(coalesce(rp.data->>'Complaint Observation', '')), '') as observation,
         nullif(btrim(coalesce(rp.data->>'Job Done', '')), '')              as job_done,
         nullif(btrim(coalesce(rp.pending_reason, '')), '')                 as pending_reason,
         nullif(btrim(coalesce(rp.engineer, '')), '')                       as visit_engineer
    from public.reports rp
   where (btrim(coalesce(c.call_number, '')) <> '' and rp.call_number = c.call_number)
      or (btrim(coalesce(c.ucn, '')) <> '' and rp.ucn = c.ucn)
   order by rp.updated_at desc nulls last, rp.id desc
   limit 1
) v on true

-- EVERY visit, as the register writes them: "date : what was done", newest
-- first. A visit with nothing written still shows its date, so a call that was
-- attended and left blank does not read as never visited.
left join lateral (
  select string_agg(
           to_char(coalesce(rp.visit_at, rp.updated_at), 'DD-Mon-YYYY') || ' : ' ||
           coalesce(
             nullif(btrim(coalesce(rp.data->>'Job Done', '')), ''),
             nullif(btrim(coalesce(rp.data->>'Complaint Observation', '')), ''),
             ''),
           E'\n' order by rp.visit_at desc nulls last, rp.id desc) as visit_details,
         count(*) as visit_count
    from public.reports rp
   where (btrim(coalesce(c.call_number, '')) <> '' and rp.call_number = c.call_number)
      or (btrim(coalesce(c.ucn, '')) <> '' and rp.ucn = c.ucn)
) h on true

-- Every spare booked against the call, with the quantity when it is not one.
left join lateral (
  select string_agg(
           btrim(s.part) || case
             when coalesce(s.qty, 1) = 1 then ''
             -- A whole number reads as "x 2", not "x 2." (FM keeps the point).
             when s.qty = trunc(s.qty) then ' x ' || trunc(s.qty)::bigint::text
             else ' x ' || trim(to_char(s.qty, 'FM999999.999'))
           end,
           ', ' order by s.id) as spares_consumed,
         count(*) as spares_count
    from public.spare_consumption s
   where btrim(coalesce(s.part, '')) <> ''
     and ((btrim(coalesce(c.call_number, '')) <> '' and s.call_number = c.call_number)
       or (btrim(coalesce(c.ucn, '')) <> '' and s.ucn = c.ucn))
) sp on true;

alter view public.field_call_review set (security_invoker = on);
grant select on public.field_call_review to authenticated;

-- ------------------------------------------------------------------------
-- 0163_call_report_review.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0163 — CALL REVIEW: has the closed call's report been looked at?
--
-- A SECOND review, and deliberately not the Daily Call Review (the user,
-- 2026-09-11: "This is different from the Daily Call Review"). The DCCR asks
-- what the failure WAS — complaint grouping, root cause, frequent failure. This
-- one asks whether the REPORT the engineer filed is fit to stand: it lists only
-- SOLVED calls, and the reviewer can do three things about one —
--
--   * book a spare the engineer did not (a Reconciliation consumption line,
--     which is what "Reco" is throughout this codebase),
--   * re-open the call, if the report does not close it,
--   * or mark it "Report Reviewed" and move on.
--
-- ONE ROW PER CALL, not a history: the question is a state ("has this been
-- reviewed?"), and the row carries who and when. Re-reviewing a call that was
-- re-opened and closed again overwrites the same row, and `reviewed_at` says
-- when it was last looked at. `status` is a text column rather than a boolean
-- because "Report Reviewed" is a phrase people will want more of later
-- (Returned to Engineer, Reviewed with Observation); a boolean would have to be
-- migrated to add the second one.
-- ===========================================================================

create table if not exists public.call_report_reviews (
  ucn              text primary key,
  status           text not null default 'Report Reviewed',
  remarks          text not null default '',
  reviewed_by      uuid,
  reviewed_by_name text not null default '',
  reviewed_at      timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

comment on table public.call_report_reviews is
  'Call Review (/call-review): has this solved call''s report been reviewed. One row per UCN.';

create index if not exists call_report_reviews_status_idx
  on public.call_report_reviews (status);

alter table public.call_report_reviews enable row level security;

-- WHO the reviewer was is the database's to say, exactly as it is on a call
-- (0113): a caller-supplied id is discarded. A review record naming somebody
-- who did not do the reviewing is worse than one naming nobody.
create or replace function public.call_report_reviews_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.reviewed_by := coalesce(auth.uid(), new.reviewed_by);
  new.reviewed_at := now();
  new.updated_at  := now();
  return new;
end $$;

drop trigger if exists zz_call_report_reviews_stamp on public.call_report_reviews;
create trigger zz_call_report_reviews_stamp
  before insert or update on public.call_report_reviews
  for each row execute function public.call_report_reviews_stamp();

-- READ follows the call: anyone who may see the call may see whether it has
-- been reviewed. Written as an EXISTS over the `calls` view so the whole
-- visibility stack (office roles, the reporting tree, the engineer's own calls)
-- applies without being restated here and drifting from it.
drop policy if exists crr_read on public.call_report_reviews;
create policy crr_read on public.call_report_reviews for select to authenticated
  using (exists (select 1 from public.calls c where c.ucn = call_report_reviews.ucn));

-- WRITE needs the right, and the same visibility: marking a call you cannot
-- see is not a review.
drop policy if exists crr_write on public.call_report_reviews;
create policy crr_write on public.call_report_reviews for insert to authenticated
  with check (public.has_perm('callreview.mark')
          and exists (select 1 from public.calls c where c.ucn = call_report_reviews.ucn));

drop policy if exists crr_update on public.call_report_reviews;
create policy crr_update on public.call_report_reviews for update to authenticated
  using (public.has_perm('callreview.mark')
     and exists (select 1 from public.calls c where c.ucn = call_report_reviews.ucn))
  with check (public.has_perm('callreview.mark'));

-- A review is a quality record: it is corrected by re-marking, never deleted.
drop policy if exists crr_delete on public.call_report_reviews;

grant select, insert, update on public.call_report_reviews to authenticated;

-- ---------------------------------------------------------------------------
-- THE RIGHTS. Merged into whatever each role already holds, never overwritten:
-- an administrator may have tuned these, and an overwrite is how a role loses
-- everything else it was given.
--
-- The PAGE goes to all six roles the user named. The ACTION does not go to
-- Technical Support or Zoho Migration: what makes those two read-only is what
-- they do NOT hold (0145/0155), and quietly granting a write here would undo
-- that for every future reader of the matrix. One tick on Roles & Permissions
-- grants it if that is wanted — which is the point of it being a permission.
-- ---------------------------------------------------------------------------
update public.app_roles
   set permissions = (
         select jsonb_agg(distinct p)
           from jsonb_array_elements(coalesce(permissions, '[]'::jsonb) || '["mod:/call-review"]'::jsonb) as t(p))
 where role in ('admin', 'nsm', 'rm', 'hotline', 'zoho_migration', 'technical_support');

update public.app_roles
   set permissions = (
         select jsonb_agg(distinct p)
           from jsonb_array_elements(coalesce(permissions, '[]'::jsonb) || '["callreview.mark"]'::jsonb) as t(p))
 where role in ('admin', 'nsm', 'rm', 'hotline');

-- ------------------------------------------------------------------------
-- 0165_field_failure_register.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0165 — THE FIELD FAILURE REGISTER (FFR).
--
-- The format is the Field_Failure_Register workbook's 2026 tab, and the report
-- it produces is R-SER-03 Rev 02. Raised from the Daily Call Review, because
-- that is where somebody decides a failure is worth reporting.
--
-- WHAT IS KEPT AND WHAT IS NOT. The sheet has 45 columns; 17 of them are
-- Google Forms / AutoCrat plumbing (Add Attachments, EO, Raise CAPA,
-- Update(Link), Merged Doc ID, Document Merge Status …) that exist only to make
-- a spreadsheet behave like an application. The application does not need them:
-- the document is generated here, so its id and merge status are not data.
-- The columns that are RECORD are kept, under their own names.
--
-- ONE ROW PER FFR, keyed by its number. `ucn` is the call it came from and is
-- NOT unique: a machine can fail twice.
-- ===========================================================================

create table if not exists public.field_failure_reports (
  id                    bigserial primary key,
  ffr_no                text not null unique,          -- FFR - 001/26
  ffr_date              date not null default (now() at time zone 'Asia/Kolkata')::date,
  source                text not null default 'PC',
  -- The call. `ucn` is the sheet's "CRN NO"; the names differ because the sheet
  -- predates the UCN and the two are the same thing.
  ucn                   text not null default '',
  crn_date              date,
  -- The customer and machine, as they were WHEN THE FAILURE WAS REPORTED. Copied
  -- rather than joined: Product Master is corrected over time and a report is a
  -- record of what was believed at the time it was raised.
  customer_name         text not null default '',
  place                 text not null default '',
  product_name          text not null default '',
  cover                 text not null default '',      -- WGP / OGP / AMC
  item_code             text not null default '',
  product_serial        text not null default '',
  installation_date     date,
  -- The failure.
  problem_reported      text not null default '',
  additional_problem    text not null default '',
  service_observation   text not null default '',
  problem_status        text not null default '',
  -- CAPA.
  capa_responsibility   text not null default '',
  capa_no               text not null default 'NA',
  capa_status           text not null default 'Not required',
  -- Verification and the rest of the sheet's record columns.
  verified_by           text not null default '',
  remarks               text not null default '',
  current_call_status   text not null default '',
  call_solved_at        timestamptz,
  visit_remarks         text not null default '',
  spares_consumed       text not null default '',
  call_type             text not null default '',
  ffr_status            text not null default 'Open',  -- Open / Closed
  doc_url               text not null default '',
  extra                 jsonb not null default '{}'::jsonb,
  raised_by             uuid,
  raised_by_name        text not null default '',
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now()
);

comment on table public.field_failure_reports is
  'Field Failure Register (/failure-report). Format: Field_Failure_Register 2026 tab; report R-SER-03 Rev 02.';

create index if not exists ffr_ucn_idx     on public.field_failure_reports (ucn);
create index if not exists ffr_date_idx    on public.field_failure_reports (ffr_date desc);
create index if not exists ffr_product_idx on public.field_failure_reports (product_name);
create index if not exists ffr_status_idx  on public.field_failure_reports (ffr_status);

-- ---------------------------------------------------------------------------
-- THE NUMBER. `FFR - 001/26`, restarting each year, in Asia/Kolkata.
--
-- A counter table rather than a sequence, for the reason 0125 gives about the
-- UCN: a sequence cannot restart per year without being reset by hand, and a
-- number that silently continues across a year boundary is wrong in a way
-- nobody notices until the audit.
--
-- SEEDED FROM WHAT IS ALREADY THERE. The 2026 tab reaches FFR - 035/26, so a
-- counter starting at zero would re-issue numbers that exist on paper. The
-- counter is moved up to the highest number ON RECORD for that year before it
-- hands one out — the same guard 0097 puts on the REQID.
-- ---------------------------------------------------------------------------
create table if not exists public.ffr_counters (
  yr      smallint primary key,          -- two-digit year, e.g. 26
  last_no integer not null default 0
);
alter table public.ffr_counters enable row level security;

create or replace function public.next_ffr_no()
returns text language plpgsql security definer set search_path = public as $$
declare
  v_yr  smallint := (extract(year from (now() at time zone 'Asia/Kolkata')))::int % 100;
  v_max integer;
  v_no  integer;
begin
  -- The highest number already issued for this year, however it got there —
  -- typed in, imported from the sheet, or handed out by this function. The
  -- shape test matters: a number that is not `FFR - nnn/yy` has nothing to
  -- compare, and a substring cast on one would raise rather than skip it.
  select coalesce(max(substring(ffr_no from 'FFR\s*-\s*([0-9]+)/')::int), 0)
    into v_max
    from public.field_failure_reports
   where ffr_no ~ ('^FFR\s*-\s*[0-9]+/' || lpad(v_yr::text, 2, '0') || '$');

  insert into public.ffr_counters (yr, last_no) values (v_yr, 0)
    on conflict (yr) do nothing;

  update public.ffr_counters
     set last_no = greatest(last_no, coalesce(v_max, 0)) + 1
   where yr = v_yr
  returning last_no into v_no;

  return 'FFR - ' || lpad(v_no::text, 3, '0') || '/' || lpad(v_yr::text, 2, '0');
end $$;

revoke all on function public.next_ffr_no() from public;
grant execute on function public.next_ffr_no() to authenticated;

-- ---------------------------------------------------------------------------
-- WHO RAISED IT is the database's to say, as it is on a call (0113) and on a
-- call review. A report naming somebody who did not raise it is worse than one
-- naming nobody.
-- ---------------------------------------------------------------------------
create or replace function public.ffr_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.raised_by := coalesce(auth.uid(), new.raised_by);
    if coalesce(btrim(new.ffr_no), '') = '' then
      new.ffr_no := public.next_ffr_no();
    end if;
  else
    -- The number is the record's identity: it is issued once and never edited.
    new.ffr_no := old.ffr_no;
    new.raised_by := old.raised_by;
  end if;
  new.updated_at := now();
  return new;
end $$;

drop trigger if exists zz_ffr_stamp on public.field_failure_reports;
create trigger zz_ffr_stamp before insert or update on public.field_failure_reports
  for each row execute function public.ffr_stamp();

-- A quality record is never deleted (0049's rule). An FFR raised in error is
-- closed with a remark, not removed.
--
-- THE TRIGGER IS NOT HERE, and that is module order rather than oversight:
-- block_hard_delete() belongs to `data_integrity`, which runs AFTER this module
-- in ALL_ORDER, so a fresh apply would fail on a function that does not exist
-- yet — check:replay caught exactly that. It is in 0166, filed there.
--
-- Deletion is already impossible for the application without it: there is no
-- DELETE policy below, so a delete as `authenticated` matches no rows. The
-- trigger is the second lock, for the day somebody adds one.

-- ---------------------------------------------------------------------------
-- RLS. Reading follows the CALL, so the reporting tree and the office roles
-- apply without being restated here. A report with no UCN (raised outside a
-- call) is visible to anyone who may see the register at all.
--
-- Every helper is wrapped as an InitPlan — once per query, not once per row.
-- That is CR-024's rule and it was worth 1,840 ms against 189 ms on
-- call_requests; a register that grows every week must not repeat it.
-- ---------------------------------------------------------------------------
alter table public.field_failure_reports enable row level security;

drop policy if exists ffr_read on public.field_failure_reports;
create policy ffr_read on public.field_failure_reports for select to authenticated
  using (
        (select public.can_view_all_calls())
     or raised_by = (select auth.uid())
     or coalesce(btrim(ucn), '') = ''
     or exists (select 1 from public.calls c where c.ucn = field_failure_reports.ucn)
  );

drop policy if exists ffr_write on public.field_failure_reports;
create policy ffr_write on public.field_failure_reports for insert to authenticated
  with check ((select public.has_perm('ffr.manage')));

drop policy if exists ffr_update on public.field_failure_reports;
create policy ffr_update on public.field_failure_reports for update to authenticated
  using ((select public.has_perm('ffr.manage')))
  with check ((select public.has_perm('ffr.manage')));

grant select, insert, update on public.field_failure_reports to authenticated;
grant usage, select on sequence public.field_failure_reports_id_seq to authenticated;

-- ---------------------------------------------------------------------------
-- THE RIGHTS. Merged, never overwritten — an administrator may have tuned the
-- role. The people who decide a failure is reportable are the ones who run the
-- Daily Call Review, so the right follows `review.edit`, plus the service
-- management roles.
-- ---------------------------------------------------------------------------
update public.app_roles
   set permissions = (
         select jsonb_agg(distinct p)
           from jsonb_array_elements(coalesce(permissions, '[]'::jsonb) || '["ffr.manage"]'::jsonb) as t(p))
 where role in ('admin', 'nsm', 'rm', 'rgm', 'hotline');

update public.app_roles
   set permissions = (
         select jsonb_agg(distinct p)
           from jsonb_array_elements(coalesce(permissions, '[]'::jsonb) || '["mod:/failure-report"]'::jsonb) as t(p))
 where role in ('admin', 'nsm', 'rm', 'rgm', 'hotline', 'technical_support', 'zoho_migration', 'engineer');

-- ------------------------------------------------------------------------
-- 0167_ffr_from_review.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0167 — AN FFR IS RAISED BY THE REVIEW, NOT BY A BUTTON.
--
-- The user's rule (2026-09-12): "When any call is marked as yes for Any
-- Potential Effect in DCCR, then it has to create an FFR using all the details
-- in DCCR. Date of FFR is the date review 2 completion."
--
-- WHY IN THE DATABASE. `any_potential_effect` is a GENERATED column on
-- call_reviews — YES when any of Risk to Patient / Warranty Failure / Frequent
-- Failure is YES, blank while any is unanswered (0044). The answer is therefore
-- made by writing the review, and the FFR must follow the answer rather than
-- somebody remembering to press a button afterwards. A register that depends on
-- a screen being opened is a register with holes in it.
--
-- IDEMPOTENT, and that is the whole safety of it: one FFR per call. Review 2
-- is edited, re-saved and corrected; every one of those writes fires this, and
-- all but the first must do nothing.
--
-- AND IT NEVER UNDOES ITSELF. If the answer is later changed to NO, the FFR
-- STAYS — a quality record is not deleted because somebody revised an opinion
-- (0049's rule). It is closed with a remark, by a person, on the register.
-- ===========================================================================

create or replace function public.ffr_from_review()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_ucn  text := coalesce(nullif(btrim(new.ucn), ''), '');
  v_call record;
begin
  -- Only on YES, and only once Review 2 has actually been completed: the
  -- generated column is blank until all three answers are in, so this cannot
  -- fire on a half-answered review.
  if upper(coalesce(btrim(new.any_potential_effect), '')) <> 'YES' then return new; end if;
  if v_ucn = '' then return new; end if;
  if exists (select 1 from public.field_failure_reports f where f.ucn = v_ucn) then return new; end if;

  -- THE CALL, FROM THE BASE TABLES. Not the `calls` view: it is
  -- security_invoker, so inside a definer function it would apply the CALLER's
  -- row policies — and a call this cannot see is an FFR it would fail to raise,
  -- silently, for exactly the reviewer whose answer triggered it. Same reasoning
  -- as 0125 gives for the UCN counter.
  select fc.ucn, fc.call_number, fc.reg_date, fc.party_name, fc.city, fc.state,
         fc.product_name, fc.serial, fc.item_status, fc.call_type,
         fc.warranty_start, fc.complaint_reported, fc.standard_complaint,
         fc.open_state, fc.last_status, fc.last_visit_at
    into v_call
    from (
      select * from public.field_calls where ucn = v_ucn
      union all
      select * from public.installation_calls where ucn = v_ucn
      union all
      select * from public.pm_calls where ucn = v_ucn
    ) fc
   limit 1;

  insert into public.field_failure_reports (
    source, ucn, ffr_date, crn_date,
    customer_name, place, product_name, product_serial, cover, installation_date,
    problem_reported, service_observation, problem_status,
    visit_remarks, spares_consumed, current_call_status, call_solved_at, call_type,
    capa_responsibility, capa_no, capa_status, ffr_status,
    raised_by_name, extra
  )
  values (
    'PC',
    v_ucn,
    -- THE DATE OF THE FFR IS THE DATE REVIEW 2 WAS COMPLETED (the user's rule).
    -- review2_at is stamped by 0044 when the third answer lands.
    coalesce(new.review2_at, (now() at time zone 'Asia/Kolkata')::date),
    v_call.reg_date,
    coalesce(v_call.party_name, ''), coalesce(v_call.city, ''),
    coalesce(v_call.product_name, ''), coalesce(v_call.serial, ''),
    coalesce(v_call.item_status, ''), v_call.warranty_start,
    coalesce(nullif(btrim(coalesce(v_call.complaint_reported, '')), ''),
             coalesce(v_call.standard_complaint, '')),
    -- Review 3's own field is HEADED "Service Dept Observation" — the FFR
    -- column of that name. Blank while Review 3 is outstanding, and filled by
    -- the update below when it is answered.
    coalesce(new.service_observation, ''),
    '',                                   -- Problem Status: written on the FFR
    (select coalesce(string_agg(
              to_char(coalesce(rp.visit_at, rp.updated_at), 'DD-Mon-YYYY') || ' : ' ||
              coalesce(nullif(btrim(coalesce(rp.data->>'Job Done', '')), ''),
                       nullif(btrim(coalesce(rp.data->>'Complaint Observation', '')), ''), ''),
              E'\n' order by rp.visit_at desc nulls last, rp.id desc), '')
       from public.reports rp where rp.ucn = v_ucn),
    (select coalesce(string_agg(distinct btrim(s.part), ', '), '')
       from public.spare_consumption s
      where s.ucn = v_ucn and coalesce(s.qty, 0) > 0),
    coalesce(v_call.open_state, v_call.last_status, ''),
    v_call.last_visit_at,
    coalesce(v_call.call_type, ''),
    'No closed in FFR', 'NA', 'Not required', 'Open',
    coalesce(nullif(btrim(coalesce(new.review2_by, '')), ''), 'Daily Call Review'),
    -- WHY it was raised, kept with the record: which of the three answers was
    -- YES is the finding, and "Any Potential Effect = YES" alone does not say.
    jsonb_build_object(
      'raised_by_rule', 'any_potential_effect=YES',
      'risk_to_patient', coalesce(new.risk_to_patient, ''),
      'warranty_failure', coalesce(new.warranty_failure, ''),
      'frequent_failure', coalesce(new.frequent_failure, ''),
      'review2_at', new.review2_at,
      'review2_by', coalesce(new.review2_by, ''))
  );

  return new;
end $$;

drop trigger if exists zz_ffr_from_review on public.call_reviews;
create trigger zz_ffr_from_review after insert or update on public.call_reviews
  for each row execute function public.ffr_from_review();

-- ---------------------------------------------------------------------------
-- REVIEW 3 ARRIVES LATER, and it carries the observation. When it is answered
-- the FFR's observation is filled in — but ONLY while nobody has written one on
-- the report itself: the FFR is where that text is finished, and overwriting a
-- person's wording with the review's would lose work without saying so.
-- ---------------------------------------------------------------------------
create or replace function public.ffr_observation_from_review()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if coalesce(btrim(new.service_observation), '') = '' then return new; end if;
  if coalesce(btrim(coalesce(old.service_observation, '')), '') = btrim(new.service_observation) then return new; end if;
  update public.field_failure_reports
     set service_observation = new.service_observation
   where ucn = btrim(new.ucn)
     and coalesce(btrim(service_observation), '') = '';
  return new;
end $$;

drop trigger if exists zz_ffr_observation on public.call_reviews;
create trigger zz_ffr_observation after update of service_observation on public.call_reviews
  for each row execute function public.ffr_observation_from_review();

-- ---------------------------------------------------------------------------
-- THE REGISTER, WITH THE LIVE CALL ON IT (the user: "all the Live data should
-- show in the field failure register as well for analysis and decisions").
--
-- The TABLE is the record — what was believed when the report was raised, which
-- is what the document prints. The VIEW is the record beside the call as it
-- stands NOW: its status, its latest visit, everything booked against it since.
-- The sheet's own column is called CURRENT call status, so this is the column
-- doing what its name says rather than a new idea.
--
-- security_invoker, so a reader sees only the reports and calls their role
-- allows. Without it this view would read as its owner and hand every FFR to
-- everyone (the fault 0040/0050/0057 shipped three times).
-- ---------------------------------------------------------------------------
create or replace view public.field_failure_register as
select
  f.*,
  c.open_state                      as live_call_status,
  c.last_visit_at                   as live_last_visit_at,
  c.allocated_to                    as live_engineer,
  c.party_name                      as live_customer_name,
  c.item_status                     as live_cover,
  (select count(*) from public.reports rp where rp.ucn = f.ucn)            as live_visit_count,
  (select coalesce(string_agg(distinct btrim(s.part), ', '), '')
     from public.spare_consumption s
    where s.ucn = f.ucn and coalesce(s.qty, 0) > 0)                        as live_spares_consumed,
  -- The review that raised it, as it stands now. A reviewer who later changed
  -- an answer to NO leaves the FFR standing (0049), and this is how somebody
  -- sees that happened.
  r.any_potential_effect            as live_any_potential_effect,
  r.risk_to_patient                 as live_risk_to_patient,
  r.warranty_failure                as live_warranty_failure,
  r.frequent_failure                as live_frequent_failure,
  r.complaint_grouping              as live_complaint_grouping,
  r.root_cause_keyword              as live_root_cause_keyword,
  r.spare_category                  as live_spare_category,
  r.review2_at                      as live_review2_at,
  r.review3_done                    as live_review3_done
from public.field_failure_reports f
left join public.calls c        on c.ucn = f.ucn
left join public.call_reviews r on r.ucn = f.ucn;

alter view public.field_failure_register set (security_invoker = on);
grant select on public.field_failure_register to authenticated;

-- ------------------------------------------------------------------------
-- 0168_ffr_weekly_review.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0168 — THE FFR IS REVIEWED WEEKLY, and the review is recorded.
--
-- The user's ask (2026-09-12) with the Google Form it replaces: "The FFR gets
-- reviewed every week and I should have the provision to update certain fields
-- as part of review." The form updates Problem Status, Service Dept
-- Observation, the three CAPA columns, FFR Status and an attachment — keyed on
-- the UCN and the FFR number.
--
-- Two columns the register did not have:
--
--  * THE ATTACHMENT. The form's "Attachment(if any)" points at a Drive folder;
--    this holds the link and the file's name, the way the call's supporting
--    documents do. The file itself stays in Drive — this application does not
--    hold files, and starting now would be a decision rather than a column.
--
--  * WHEN IT WAS LAST REVIEWED. The whole point of a weekly cycle is knowing
--    which reports have not been looked at this week, and that cannot be read
--    off `updated_at` — any edit moves that. Stamped only by the review.
-- ===========================================================================

alter table public.field_failure_reports
  add column if not exists attachment_url    text not null default '',
  add column if not exists attachment_name   text not null default '',
  add column if not exists reviewed_at       date,
  add column if not exists reviewed_by_name  text not null default '';

comment on column public.field_failure_reports.reviewed_at is
  'The weekly FFR review. NOT updated_at: any edit moves that, and the question is which reports have not been looked at.';

create index if not exists ffr_reviewed_idx on public.field_failure_reports (reviewed_at nulls first);

-- 'Cancelled' joins Open and Closed on the form. A cancelled report is still a
-- record — it is not deleted, it is marked (0049's rule), which is exactly what
-- this status is for.
--
-- No CHECK constraint, deliberately: 0152 is the precedent. A CHECK on a
-- vocabulary column aborted a bulk load PART-WRITTEN when a value outside it
-- appeared, leaving a half-updated table. A word the list does not know now
-- lands in the data and shows on the register as itself, which is how somebody
-- notices, rather than the row never arriving.

-- ---------------------------------------------------------------------------
-- THE VIEW IS DROPPED AND REBUILT, not replaced.
--
-- `create or replace view` can only APPEND columns, and this one selects `f.*`
-- — so the four columns added above arrive in the MIDDLE of its output, before
-- live_call_status. The replace fails with "cannot change name of view column",
-- which is precisely what happened here on the first apply.
--
-- Nothing depends on this view but the register screen, so dropping it costs
-- nothing. security_invoker is re-asserted below because a rebuilt view does
-- not keep it — the fault 0040/0050/0057 shipped three times, each time handing
-- every row to every signed-in user.
-- ---------------------------------------------------------------------------
drop view if exists public.field_failure_register;
create view public.field_failure_register as
select
  f.*,
  c.open_state                      as live_call_status,
  c.last_visit_at                   as live_last_visit_at,
  c.allocated_to                    as live_engineer,
  c.party_name                      as live_customer_name,
  c.item_status                     as live_cover,
  (select count(*) from public.reports rp where rp.ucn = f.ucn)            as live_visit_count,
  (select coalesce(string_agg(distinct btrim(s.part), ', '), '')
     from public.spare_consumption s
    where s.ucn = f.ucn and coalesce(s.qty, 0) > 0)                        as live_spares_consumed,
  r.any_potential_effect            as live_any_potential_effect,
  r.risk_to_patient                 as live_risk_to_patient,
  r.warranty_failure                as live_warranty_failure,
  r.frequent_failure                as live_frequent_failure,
  r.complaint_grouping              as live_complaint_grouping,
  r.root_cause_keyword              as live_root_cause_keyword,
  r.spare_category                  as live_spare_category,
  r.review2_at                      as live_review2_at,
  r.review3_done                    as live_review3_done
from public.field_failure_reports f
left join public.calls c        on c.ucn = f.ucn
left join public.call_reviews r on r.ucn = f.ucn;

alter view public.field_failure_register set (security_invoker = on);
grant select on public.field_failure_register to authenticated;

-- ---------------------------------------------------------------------------
-- THE REVIEW STAMP. Who reviewed it is the database's to say, as the raiser is
-- (0165) and as a call's registrant is (0113). `reviewed_at` is only moved when
-- the caller actually sets it, so an ordinary edit to a report does not make it
-- look reviewed.
-- ---------------------------------------------------------------------------
create or replace function public.ffr_stamp()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.raised_by := coalesce(auth.uid(), new.raised_by);
    if coalesce(btrim(new.ffr_no), '') = '' then
      new.ffr_no := public.next_ffr_no();
    end if;
  else
    -- The number is the record's identity: issued once, never edited.
    new.ffr_no := old.ffr_no;
    new.raised_by := old.raised_by;
    -- A weekly review is a DATE somebody set, not a side effect of saving.
    if new.reviewed_at is distinct from old.reviewed_at and new.reviewed_at is not null then
      new.reviewed_by_name := coalesce(nullif(btrim(new.reviewed_by_name), ''), new.reviewed_by_name);
    end if;
  end if;
  new.updated_at := now();
  return new;
end $$;

-- ------------------------------------------------------------------------
-- 0169_ffr_backfill.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0169 — RAISE THE FFRs THAT ARE ALREADY DUE ("as a 1 time activity — create
-- all the FFRs till date", 2026-09-12).
--
-- 0167 raises an FFR when a review is WRITTEN with Any Potential Effect = YES.
-- Every review already answered YES before that shipped has no report. This is
-- the catch-up, and three things had to change to make it safe:
--
--  1. THE NUMBER MUST BE IN THE REVIEW'S YEAR, not this one. next_ffr_no() read
--     the current year, so a 2025 review would have been numbered /26. It now
--     takes the year, defaulting to today's.
--
--  2. ONE CODE PATH. The trigger and the backfill must produce identical
--     records or the catch-up is a second, subtly different register. The
--     insert is now raise_ffr(), called by both.
--
--  3. A DRY RUN FIRST. The backfill reports what it WOULD create before it
--     creates anything, because nobody should discover the count afterwards —
--     and because the numbers it issues are permanent.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- The number, in a stated year. Dropping the old signature first: adding a
-- defaulted argument beside it would leave `next_ffr_no()` ambiguous between
-- two functions, and Postgres refuses that at the call site rather than here.
-- ---------------------------------------------------------------------------
drop function if exists public.next_ffr_no();

create or replace function public.next_ffr_no(p_yr smallint default null)
returns text language plpgsql security definer set search_path = public as $$
declare
  v_yr  smallint := coalesce(p_yr, (extract(year from (now() at time zone 'Asia/Kolkata')))::int % 100);
  v_max integer;
  v_no  integer;
begin
  -- The highest number already issued FOR THAT YEAR, however it got there —
  -- typed in, imported from the sheet, or handed out here. The shape test
  -- matters: a number that is not `FFR - nnn/yy` has nothing to compare, and a
  -- substring cast on one would raise rather than skip it.
  select coalesce(max(substring(ffr_no from 'FFR\s*-\s*([0-9]+)/')::int), 0)
    into v_max
    from public.field_failure_reports
   where ffr_no ~ ('^FFR\s*-\s*[0-9]+/' || lpad(v_yr::text, 2, '0') || '$');

  insert into public.ffr_counters (yr, last_no) values (v_yr, 0)
    on conflict (yr) do nothing;

  update public.ffr_counters
     set last_no = greatest(last_no, coalesce(v_max, 0)) + 1
   where yr = v_yr
  returning last_no into v_no;

  return 'FFR - ' || lpad(v_no::text, 3, '0') || '/' || lpad(v_yr::text, 2, '0');
end $$;

revoke all on function public.next_ffr_no(smallint) from public;
grant execute on function public.next_ffr_no(smallint) to authenticated;

-- ---------------------------------------------------------------------------
-- RAISE ONE. The single definition of what an FFR made from a review contains;
-- the trigger and the backfill both call it, so the catch-up cannot quietly
-- differ from what the system produces from now on.
--
-- Returns the number issued, or NULL when there is already a report for that
-- call — which is what makes calling it twice harmless.
-- ---------------------------------------------------------------------------
create or replace function public.raise_ffr(p_review public.call_reviews)
returns text language plpgsql security definer set search_path = public as $$
declare
  v_ucn  text := coalesce(nullif(btrim(p_review.ucn), ''), '');
  v_call record;
  v_date date;
  v_no   text;
begin
  if v_ucn = '' then return null; end if;
  if exists (select 1 from public.field_failure_reports f where f.ucn = v_ucn) then return null; end if;

  -- THE DATE OF THE FFR IS THE DATE REVIEW 2 WAS COMPLETED (the user's rule).
  v_date := coalesce(p_review.review2_at, (now() at time zone 'Asia/Kolkata')::date);
  -- …and therefore so is its YEAR. A 2025 review numbered /26 would be wrong on
  -- the face of the document.
  v_no := public.next_ffr_no((extract(year from v_date)::int % 100)::smallint);

  -- The call, FROM THE BASE TABLES. Not the `calls` view: it is
  -- security_invoker, so inside a definer it would apply the CALLER's row
  -- policies — and a call this cannot see is a report it fails to raise,
  -- silently. Same reasoning 0125 gives for the UCN counter.
  select fc.reg_date, fc.party_name, fc.city, fc.product_name, fc.serial,
         fc.item_status, fc.call_type, fc.warranty_start,
         fc.complaint_reported, fc.standard_complaint,
         fc.open_state, fc.last_status, fc.last_visit_at
    into v_call
    from (
      select * from public.field_calls where ucn = v_ucn
      union all
      select * from public.installation_calls where ucn = v_ucn
      union all
      select * from public.pm_calls where ucn = v_ucn
    ) fc
   limit 1;

  insert into public.field_failure_reports (
    ffr_no, source, ucn, ffr_date, crn_date,
    customer_name, place, product_name, product_serial, cover, installation_date,
    problem_reported, service_observation, problem_status,
    visit_remarks, spares_consumed, current_call_status, call_solved_at, call_type,
    capa_responsibility, capa_no, capa_status, ffr_status,
    raised_by_name, extra
  )
  values (
    v_no, 'PC', v_ucn, v_date, v_call.reg_date,
    coalesce(v_call.party_name, ''), coalesce(v_call.city, ''),
    coalesce(v_call.product_name, ''), coalesce(v_call.serial, ''),
    coalesce(v_call.item_status, ''), v_call.warranty_start,
    coalesce(nullif(btrim(coalesce(v_call.complaint_reported, '')), ''),
             coalesce(v_call.standard_complaint, '')),
    coalesce(p_review.service_observation, ''),
    '',
    (select coalesce(string_agg(
              to_char(coalesce(rp.visit_at, rp.updated_at), 'DD-Mon-YYYY') || ' : ' ||
              coalesce(nullif(btrim(coalesce(rp.data->>'Job Done', '')), ''),
                       nullif(btrim(coalesce(rp.data->>'Complaint Observation', '')), ''), ''),
              E'\n' order by rp.visit_at desc nulls last, rp.id desc), '')
       from public.reports rp where rp.ucn = v_ucn),
    (select coalesce(string_agg(distinct btrim(s.part), ', '), '')
       from public.spare_consumption s
      where s.ucn = v_ucn and coalesce(s.qty, 0) > 0),
    coalesce(v_call.open_state, v_call.last_status, ''),
    v_call.last_visit_at,
    coalesce(v_call.call_type, ''),
    'No closed in FFR', 'NA', 'Not required', 'Open',
    coalesce(nullif(btrim(coalesce(p_review.review2_by, '')), ''), 'Daily Call Review'),
    jsonb_build_object(
      'raised_by_rule', 'any_potential_effect=YES',
      'risk_to_patient', coalesce(p_review.risk_to_patient, ''),
      'warranty_failure', coalesce(p_review.warranty_failure, ''),
      'frequent_failure', coalesce(p_review.frequent_failure, ''),
      'review2_at', p_review.review2_at,
      'review2_by', coalesce(p_review.review2_by, ''))
  );

  return v_no;
end $$;

-- The trigger now calls it, so there is one definition of the record.
create or replace function public.ffr_from_review()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if upper(coalesce(btrim(new.any_potential_effect), '')) <> 'YES' then return new; end if;
  perform public.raise_ffr(new);
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- THE CATCH-UP.
--
-- DRY RUN BY DEFAULT. The numbers this issues are permanent, and a count
-- discovered afterwards is a count discovered too late:
--
--   select * from public.backfill_ffrs();            -- what it WOULD create
--   select * from public.backfill_ffrs(false);       -- create them
--
-- IN REVIEW ORDER, oldest first, so the numbering runs the way the register
-- was written rather than the order rows happen to come back. Deterministic on
-- a re-run for the same reason.
--
-- Idempotent: raise_ffr() returns NULL for a call that already has a report, so
-- running it twice creates nothing the second time.
-- ---------------------------------------------------------------------------
create or replace function public.backfill_ffrs(p_dry_run boolean default true)
returns table (ucn text, ffr_no text, ffr_date date, customer text, product text, note text)
language plpgsql security definer set search_path = public as $$
declare
  r      public.call_reviews;
  v_no   text;
  v_call record;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator may back-fill the Field Failure Register.';
  end if;

  for r in
    select cr.* from public.call_reviews cr
     where upper(coalesce(btrim(cr.any_potential_effect), '')) = 'YES'
       and coalesce(btrim(cr.ucn), '') <> ''
       and not exists (select 1 from public.field_failure_reports f where f.ucn = cr.ucn)
     order by cr.review2_at nulls last, cr.ucn
  loop
    select c.party_name, c.product_name into v_call
      from public.calls c where c.ucn = r.ucn limit 1;

    if p_dry_run then
      ucn := r.ucn;
      -- The number is NOT issued on a dry run: reserving one and not using it
      -- would leave a gap in a numbered series that somebody has to explain.
      ffr_no := '(would be issued in ' || coalesce(to_char(r.review2_at, 'YYYY'), 'this year') || ')';
      ffr_date := r.review2_at;
      customer := coalesce(v_call.party_name, '');
      product := coalesce(v_call.product_name, '');
      note := 'would create';
      return next;
    else
      v_no := public.raise_ffr(r);
      if v_no is not null then
        ucn := r.ucn; ffr_no := v_no; ffr_date := r.review2_at;
        customer := coalesce(v_call.party_name, '');
        product := coalesce(v_call.product_name, '');
        note := 'created';
        return next;
      end if;
    end if;
  end loop;
end $$;

revoke all on function public.backfill_ffrs(boolean) from public;
grant execute on function public.backfill_ffrs(boolean) to authenticated;

commit;
